let catalog=[];
const select=document.getElementById('book'), pageInput=document.getElementById('page'), image=document.getElementById('book-image'), status=document.getElementById('book-status');
function openPage(push=true) {
  const book=catalog.find(item=>item.id===select.value),page=Number(pageInput.value);
  if(!book || !Number.isInteger(page) || page<1 || page>book.pages){status.textContent='Escolha uma página entre 1 e '+(book?.pages || 1)+'.';return;}
  pageInput.max=book.pages;document.title=book.name+' · página '+page;status.textContent='Carregando '+book.name+', página impressa '+page+' (posição '+(page+book.pdfOffset)+' do PDF)…';image.hidden=true;image.src=`/api/books/${book.id}/pages/${page}`;image.alt=book.name+', página impressa '+page;document.getElementById('prev').disabled=page<=1;document.getElementById('next').disabled=page>=book.pages;
  if(push)history.replaceState(null,'',`livro.html?book=${book.id}&page=${page}`);
}
image.onload=()=>{image.hidden=false;status.textContent='Página impressa '+pageInput.value+' · use Ampliar ou o zoom do aparelho para ler.';};image.onerror=()=>{status.textContent='Não foi possível carregar esta página. Recarregue; se persistir, informe o livro e a página ao administrador.';};
document.getElementById('page-form').addEventListener('submit',event=>{event.preventDefault();openPage();});document.getElementById('prev').addEventListener('click',()=>{pageInput.value=Number(pageInput.value)-1;openPage();});document.getElementById('next').addEventListener('click',()=>{pageInput.value=Number(pageInput.value)+1;openPage();});select.addEventListener('change',()=>{pageInput.value=Math.min(Number(pageInput.value),catalog.find(item=>item.id===select.value).pages);openPage();});document.getElementById('zoom').addEventListener('click',()=>{document.getElementById('book-wrap').classList.toggle('zoomed');document.getElementById('zoom').textContent=document.getElementById('book-wrap').classList.contains('zoomed')?'Ajustar à tela':'Ampliar';});
(async()=>{try{const response=await fetch('/api/books',{cache:'no-store'}),result=await response.json();if(!response.ok)throw new Error(result.error);catalog=result.books;select.innerHTML=catalog.map(book=>`<option value="${book.id}">${book.name}</option>`).join('');const query=new URLSearchParams(location.search);select.value=catalog.some(item=>item.id===query.get('book'))?query.get('book'):'livro1';pageInput.value=query.get('page')||1;openPage();}catch(error){status.textContent=error.message+' Entre na mesa para consultar os livros.';}})();
